// Secure Express.js Application with Improved Secret Management
// Security-reviewed version with secret management best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// Enhanced configuration loading with validation
const config = {
  port: parseInt(process.env.PORT) || 3000,
  host: process.env.HOST || '0.0.0.0',
  nodeEnv: process.env.NODE_ENV || 'development',

  // Security-critical settings - MUST be provided in production
  jwtSecret: process.env.ACCESS_TOKEN_SECRET,

  // Optional configs with safe defaults
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100,

  // CORS settings
  allowedOrigins: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
    : ['http://localhost:3000'],
};

// Validate required configuration
const validateConfig = () => {
  const errors = [];

  if (config.nodeEnv === 'production' && !config.jwtSecret) {
    errors.push('ACCESS_TOKEN_SECRET is required in production');
  }

  if (config.jwtSecret && config.jwtSecret.length < 32) {
    errors.push('ACCESS_TOKEN_SECRET should be at least 32 characters long');
  }

  if (errors.length > 0) {
    console.error('Configuration Errors:', errors);
    // In production, we should exit rather than run with insecure config
    if (config.nodeEnv === 'production') {
      process.exit(1);
    }
    // In dev, we warn but continue (with clearly insecure fallback for local dev only)
    console.warn('WARNING: Using development fallback JWT secret - DO NOT USE IN PRODUCTION');
  }
};

validateConfig();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    }
  }
}));

// CORS Configuration
const corsOptions = {
  origin: config.allowedOrigins,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
};
app.use(cors(corsOptions));

// Rate Limiting
const limiter = rateLimit({
  windowMs: config.rateLimitWindowMs,
  max: config.rateLimitMax,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body Parsing
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Improved Authentication Middleware with better error handling
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ 
      error: 'Unauthorized', 
      message: 'Missing or malformed authorization header' 
    });
  }

  const token = authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Unauthorized', 
      message: 'No token provided' 
    });
  }

  try {
    // Never use fallback secrets in production
    const secret = config.nodeEnv === 'production' 
      ? config.jwtSecret 
      : (config.jwtSecret || 'dev-fallback-secret-change-me-in-real-development');

    // Additional validation for development fallback
    if (config.nodeEnv !== 'production' && secret === 'dev-fallback-secret-change-me-in-real-development') {
      console.warn('Using development JWT secret - rotate immediately before any testing');
    }

    const decoded = jwt.verify(token, secret);
    req.user = decoded;
    next();
  } catch (err) {
    // Don't leak specific JWT error details in production
    if (config.nodeEnv === 'production') {
      return res.status(401).json({ 
        error: 'Unauthorized', 
        message: 'Invalid token' 
      });
    }

    // More detailed errors in development
    return res.status(401).json({ 
      error: 'Unauthorized', 
      message: err.message 
    });
  }
}

// Optional: Role-based authorization
function authorizeRole(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'Unauthorized', 
        message: 'Authentication required' 
      });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Forbidden', 
        message: 'Insufficient permissions' 
      });
    }
    next();
  };
}

// Health Check Endpoint (Public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: config.nodeEnv
  });
});

// Protected Users Endpoint
app.get('/users', authenticateToken, (req, res) => {
  // In a real app, you'd fetch from database and filter based on user permissions
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  // Filter sensitive data based on user role
  if (req.user.role !== 'admin') {
    return res.json(users.map(user => ({
      id: user.id,
      name: user.name
      // Email hidden for non-admins
    })));
  }

  res.json(users);
});

// Example POST endpoint with validation
app.post('/users', 
  authenticateToken,
  authorizeRole('admin'), // Only admins can create users
  [
    body('email').isEmail().normalizeEmail(),
    body('name').trim().isLength({ min: 2, max: 50 }).escape(),
    body('role').isIn(['admin', 'user']).optional(),
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }
      next();
    }
  ],
  (req, res) => {
    // In real app, save to database
    const newUser = {
      id: Date.now(), // Simple ID generation
      ...req.body
    };
    res.status(201).json({ 
      message: 'User created', 
      user: newUser 
    });
  }
);

// 404 Handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  // Log full error details internally (but be careful not to log secrets!)
  const logMessage = `${new Date().toISOString()} - Error: ${err.message}`;
  console.error(logMessage);

  // Only include stack trace in development
  const response = {
    error: config.nodeEnv === 'production' ? 
      'Internal Server Error' : 
      err.message,
  };

  if (config.nodeEnv !== 'production') {
    response.stack = err.stack;
    response.timestamp = new Date().toISOString();
  }

  const statusCode = err.status || (res.statusCode === 200 ? 500 : res.statusCode);
  res.status(statusCode).json(response);
});

const server = app.listen(config.port, config.host, () => {
  console.log(`Server running on http://${config.host}:${config.port}`);
  console.log(`Environment: ${config.nodeEnv}`);

  // Log configuration status (without revealing secrets)
  console.log(`JWT Secret: ${config.jwtSecret ? 'SET' : 'MISSING (using fallback in dev only)'}`);
  console.log(`Rate Limiting: ${config.rateLimitMax} requests per ${config.rateLimitWindowMs/1000/60} minutes`);
  console.log(`CORS Origins: ${config.allowedOrigins.join(', ')}`);
});

// Graceful shutdown
const shutdown = () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;

# Secret Management Guide for Express.js Applications

This document outlines best practices for managing secrets in Node.js/Express.js applications, addressing the vulnerabilities found in the original implementation.

## Problems with Original Approach

### 1. Direct .env File Loading
```javascript
require('dotenv').config(); // Loads secrets directly from .env
```

**Issues**:
- `.env` files frequently get accidentally committed to Git
- No distinction between environments (all secrets in one file)
- No validation of required secrets
- Secrets remain in server memory longer than necessary

### 2. Hardcoded Fallback Secrets
```javascript
jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'fallback-secret', ...)
```

**Issues**:
- Weak fallback secrets that are guessable
- Creates a false sense of security
- Deployments might unknowingly use fallback secrets
- Fallback secrets often get leaked in error messages

## Improved Implementation

### 1. Configuration Validation

The improved `app.js` includes comprehensive configuration validation:

```javascript
const validateConfig = () => {
  const errors = [];

  // Required in production
  if (config.nodeEnv === 'production' && !config.jwtSecret) {
    errors.push('ACCESS_TOKEN_SECRET is required in production');
  }

  // Strength requirements
  if (config.jwtSecret && config.jwtSecret.length < 32) {
    errors.push('ACCESS_TOKEN_SECRET should be at least 32 characters long');
  }

  if (errors.length > 0) {
    console.error('Configuration Errors:', errors);
    // Fail fast in production
    if (config.nodeEnv === 'production') {
      process.exit(1);
    }
  }
};
```

### 2. Environment-Aware Secret Usage

```javascript
// Never use fallback secrets in production
const secret = config.nodeEnv === 'production' 
  ? config.jwtSecret 
  : (config.jwtSecret || 'dev-fallback-secret-change-me-in-real-development');

// Warn when using development fallback
if (config.nodeEnv !== 'production' && secret === 'dev-fallback-secret-change-me-in-real-development') {
  console.warn('Using development JWT secret - rotate immediately before any testing');
}
```

### 3. Secure Error Handling

```javascript
// Don't leak specific JWT error details in production
if (config.nodeEnv === 'production') {
  return res.status(401).json({ 
    error: 'Unauthorized', 
    message: 'Invalid token' 
  });
}

// More detailed errors in development only
return res.status(401).json({ 
  error: 'Unauthorized', 
  message: err.message 
});
```

## Best Practices for Secret Management

### 1. Never Commit .env Files
- Add `.env` to your `.gitignore`
- Use `.env.example` as a template
- Document required variables without revealing values

### 2. Use Strong, Random Secrets
Generate JWT secrets with:
```bash
openssl rand -base64 32
# or for stronger security
openssl rand -base64 64
```

### 3. Environment-Specific Configuration
Consider using different files for different environments:
- `.env.development`
- `.env.staging` 
- `.env.production`

And load them appropriately:
```javascript
const envFile = `.env.${process.env.NODE_ENV}`;
require('dotenv').config({ path: envFile });
```

### 4. Secret Rotation Strategy
1. Deploy new secret alongside old one
2. Update applications to accept both
3. Rotate all clients to use new secret
4. Remove old secret after grace period

### 5. Use Dedicated Secret Managers in Production

#### AWS Secrets Manager
```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function getSecret(secretName) {
  const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
  return JSON.parse(data.SecretString);
}

// Usage
const secrets = await getSecret('myapp/prod/jwt-secret');
process.env.ACCESS_TOKEN_SECRET = secrets.jwtSecret;
```

#### HashiCorp Vault
```javascript
const vault = require('node-vault')({
  apiVersion: 'v1',
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN
});

const secretData = await vault.read('secret/data/myapp/jwt');
process.env.ACCESS_TOKEN_SECRET = secretData.data.data.jwt_secret;
```

#### Azure Key Vault
```javascript
const { DefaultAzureCredential } = require("@azure/identity");
const { SecretClient } = require("@azure/keyvault-secrets");

const credential = new DefaultAzureCredential();
const client = new SecretClient(process.env.KEY_VAULT_URL, credential);

const secret = await client.getSecret("JwtSecret");
process.env.ACCESS_TOKEN_SECRET = secret.value;
```

### 6. Kubernetes Secrets (if applicable)
```yaml
# k8s-secret.yaml
apiVersion: v1
kind: Secret
metadata:
  name: app-secrets
type: Opaque
data:
  ACCESS_TOKEN_SECRET: <base64-encoded-secret>

# Deployment reference
envFrom:
- secretRef:
    name: app-secrets
```

## Development vs Production Strategies

### Development
- Use `.env` files (gitignored)
- Generate strong local secrets
- Allow convenient fallbacks with clear warnings
- Never use production secrets in development

### Production
- Use dedicated secret managers (AWS Secrets Manager, Vault, etc.)
- Enforce strict validation at startup
- Implement secret rotation without downtime
- Monitor for secret usage anomalies
- Use short-lived credentials where possible
- Implement least privilege access

## Checking for Accidental Committed Secrets

Regularly scan your repository for leaked secrets:

```bash
# Install git-secrets
brew install git-secrets   # macOS
# or
apt-get install git-secrets # Ubuntu

# Install hooks
git secrets --install
git secrets --register-aws

# Scan repository
git secrets --scan

# Scan specific commit range
git secrets --scan-history
```

Or use specialized tools:
- [git-secrets](https://github.com/awslabs/git-secrets)
- [truffleHog](https://github.com/trufflesecurity/truffleHog)
- [detect-secrets](https://github.com/Yelp/detect-secrets)
- [Gitleaks](https://github.com/zricethezav/gitleaks)

## Conclusion

Proper secret management is crucial for application security. The improved implementation addresses the key vulnerabilities by:

1. Removing dangerous fallback secrets in production
2. Adding comprehensive configuration validation
3. Implementing environment-aware error handling
4. Providing clear migration paths to production secret managers
5. Including development safeguards with appropriate warnings

Remember: The strongest application security can be undermined by a single leaked secret. Treat secret management as a continuous process, not a one-time setup.

