// Secure version of app.js with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');
const jwt = require('jsonwebtoken');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) return res.sendStatus(401);

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'fallback-secret-for-dev', (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Input validation schemas
const userIdSchema = {
  params: Joi.object({
    id: Joi.number().integer().positive().required()
  })
};

const userSchema = {
  body: Joi.object({
    name: Joi.string().min(2).max(50).required(),
    email: Joi.string().email().required()
  })
};

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', authenticateToken, (req, res) => {
  // In real app: fetch user-specific data based on req.user
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.get('/users/:id', authenticateToken, validate(userIdSchema), (req, res) => {
  const userId = req.params.id;
  // Safe to use userId in database queries
  res.json({ id: userId, message: 'User data would go here' });
});

app.post('/users', authenticateToken, validate(userSchema), (req, res) => {
  // Create new user with validated data
  const { name, email } = req.body;
  res.status(201).json({ 
    id: Date.now(), // Simplified ID generation
    name, 
    email,
    message: 'User created successfully'
  });
});

// Error handling
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ 
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

