// Enhanced version of app.js with security improvements

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// === SECURITY MIDDLEWARE ===

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    }
  }
}));

// Request logging (avoid logging sensitive data)
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400, // Only log errors
  stream: {
    write: (message) => console.log(message.trim())
  }
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// === ROUTES ===

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  // In a real app, this would require authentication
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example of how a protected route would look
/*
app.get('/profile', authenticateToken, (req, res) => {
  res.json({ 
    userId: req.user.id,
    message: 'Profile data would go here'
  });
});
*/

// === ERROR HANDLING ===

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// Central error handler (prevents leak of stack traces)
app.use((err, req, res, next) => {
  console.error(`${new Date().toISOString()} - ${err.stack}`);

  // Never send detailed errors to client in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'Internal server error'
  };

  // Log security-relevant errors
  if (err.type === 'entity.too large') {
    console.warn(`Possible DoS attempt: ${err.message}`);
  }

  res.status(err.status || 500).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
});

module.exports = app;

