const { validationResult } = require('express-validator');
const { query } = require('express-validator');

// Load environment variables safely
// In production, these should come from a secrets manager
const dotenv = require('dotenv');
const dotenvExpand = require('dotenv-expand');

// Load environment-specific file
const envFile = `.env.${process.env.NODE_ENV || 'development'}`;
const result = dotenv.config({ path: envFile });

if (result.error) {
  console.warn(`Warning: Could not load ${envFile}:`, result.error.message);
}

// Expand variables (e.g., for nested variable references)
dotenvExpand.expand(result);

// Validate required environment variables in non-test environments
if (process.env.NODE_ENV !== 'test') {
  const requiredVars = ['PORT'];
  // Add other required secrets based on functionality
  // const requiredVars = ['PORT', 'DATABASE_URL', 'JWT_SECRET', 'API_KEY'];

  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error(`Error: Missing required environment variables: ${missingVars.join(', ')}`);
    process.exit(1);
  }
}

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Body parsing middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging (avoid logging sensitive info)
app.use((req, res, next) => {
  // Log request metadata but avoid logging headers that might contain secrets
  const safeHeaders = { ...req.headers };
  // Remove potentially sensitive headers
  delete safeHeaders.authorization;
  delete safeHeaders.cookie;
  delete safeHeaders['x-api-key'];

  console.log(`${new Date().toISOString()} ${req.method} ${req.path}`, {
    headers: safeHeaders,
    ip: req.ip || req.connection.remoteAddress
  });
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  // Avoid exposing internal system info in health checks in production
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    ...(process.env.NODE_ENV !== 'production' && { uptime: process.uptime() })
  };

