// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handler - be careful not to leak secrets in error messages
app.use((err, req, res, next) => {
  // Log full error for internal debugging
  console.error(`${new Date().toISOString()} Error:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : '[REDACTED]',
    url: req.originalUrl,
    method: req.method,
    ip: req.ip || req.connection.remoteAddress
  });

  // Determine what to send to client based on environment
  const status = err.status || 500;
  let message;

  if (process.env.NODE_ENV === 'production') {
    // In production, don't leak internal details
    message = 'Internal server error';

    // Only expose specific error types to clients
    switch (status) {
      case 400:
        message = err.message || 'Bad request';
        break;
      case 401:
        message = 'Unauthorized';
        break;
      case 403:
        message = 'Forbidden';
        break;
      case 404:
        message = 'Not found';
        break;
      case 429:
        message = 'Too many requests';
        break;
      default:
        message = 'Internal server error';
    }
  } else {
    // In development/testing, show more details
    message = err.message || 'Internal server error';
  }

  res.status(status).json({ error: message });
});

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error(`${new Date().toISOString()} Unhandled Rejection at:`, promise, 'reason:', reason);
