// Production-ready Express.js application with security best practices
// Including proper environment variable and secrets management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');

// Load environment variables from .env file (only in non-production)
// In production, use platform-specific secrets management
if (process.env.NODE_ENV !== 'production' && process.env.NODE_ENV !== 'test') {
  require('dotenv').config();
}

const app = express();

// Validate required environment variables in non-dev environments
const validateEnv = () => {
  const requiredVars = ['PORT'];
  // Add more required vars for production
  if (process.env.NODE_ENV === 'production') {
    requiredVars.push(
      'DATABASE_URL',
      // Add other production-required secrets here
    );
  }

  const missing = requiredVars.filter(var => !process.env[var]);
  if (missing.length > 0) {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }
};

validateEnv();

// Security middleware
app.use(helmet({
  // Customize helmet settings based on your needs
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'"],
    },
  },
  // Disable in development if needed for debugging
  ...(process.env.NODE_ENV === 'production' && {}),
}));

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: Number(process.env.RATE_LIMIT_WINDOW_MS || '900000'), // 15 minutes default
  max: Number(process.env.RATE_LIMIT_MAX_REQUESTS || 
    (process.env.NODE_ENV === 'production' ? 100 : 1000)),
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false,
});
app.use(limiter);

// Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Body parsing middleware
app.use(express.json({ limit: process.env.BODY_LIMIT || '100kb' }));
app.use(express.urlencoded({ extended: true, limit: process.env.BODY_LIMIT || '100kb' }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with validation
app.get('/users', [
  // Example validation for query parameters
  // query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  // query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, this would come from a database
    // Database connection would use process.env.DATABASE_URL
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
]);

// Example POST endpoint with validation
app.post('/users', [
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  body('email').isEmail().normalizeEmail(),
  body('age').optional().isInt({ min: 0, max: 150 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, save to database and return created user
    // Database interaction would use secrets from environment
    res.status(201).json({ 
      id: Date.now(), // Mock ID - replace with actual DB ID
      ...req.body 
    });
  }
]);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Error handler
app.use((err, req, res, next) => {
  // Log error with timestamp and environment info
  console.error(`${new Date().toISOString()} - [${process.env.NODE_ENV}] - Error:`, {
    message: err.message,
    // Only include stack trace in non-production
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });

  // Don't leak stack trace or internal details in production
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message || 'Internal Server Error',
    ...(process.env.NODE_ENV !== 'production' && {
      // Add more debug info in development
      timestamp: new Date().toISOString(),
      url: req.originalUrl,
      method: req.method
    })
  };

  res.status(err.status || 500).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

  // Log enabled features (without exposing secrets)
  console.log(`Features enabled:`);
  console.log(`- Security headers: ${process.env.NODE_ENV === 'production' ? 'Full' : 'Development'}`);
  console.log(`- CORS origin: ${corsOptions.origin}`);
  console.log(`- Rate limiting: ${limiter.max} requests per ${limiter.windowMs/1000/60} minutes`);
  console.log(`- Logging: ${morgan}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;
